"""Freeze the visible palette-capture scroll failure without retagging guards."""
from pathlib import Path
import argparse,hashlib,json,shutil
from PIL import Image
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--base',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=False);cases=[];bindings={}
 def bind(f):bindings[str(f.resolve())]=dict(bytes=f.stat().st_size,sha256=sha(f))
 for name,frame in [('octopus-easy',458),('twinbee-easy',479),('pentarou-easy',479)]:
  packet=a.base/'hud-native-v1'/name;run=packet/'baseline-early';events=[json.loads(s)for s in(run/'oam-bus.jsonl').read_text().splitlines()];epochs={r['start']['frame']:r for r in[json.loads(s)for s in(run/'epochs.jsonl').read_text().splitlines()]};frames={r['finished']['frame']:r for r in[json.loads(s)for s in(run/'hud-frames.jsonl').read_text().splitlines()]};ep=epochs[frame];state=ep['start_state'];assert state['ppu.tmpVideoRamAddr']==0x3300 and frames[frame]['start']['ram']['DisableScreenFlag']==0 and ep['dma']['complete']['exact_source'];relevant=[x for x in events if x.get('ppu',{}).get('frame')==frame and x['kind']in ['PPU-mapper-write','2001-mask','routine-entry','routine-return','4014-start','4014-complete-after-next-LDX']];addresses=[x for x in relevant if x['kind']=='PPU-mapper-write'and x['address']==0x2006 and x['nmi_depth']==1];assert [x['value']for x in addresses[-2:]]==[0x3f,0];last=addresses[-1];scrolls=[x for x in relevant if x['kind']=='PPU-mapper-write'and x['address']==0x2005 and x['nmi_depth']==1];assert len(scrolls)==2 and scrolls[-1]['ppu']['cpu']<last['ppu']['cpu'];assert epochs[frame+1]['start_state']['ppu.tmpVideoRamAddr']==0
  for n in [frame-1,frame,frame+1]:
   f=run/f'frame-{n:06}.argb';bind(f);im=Image.frombytes('RGBA',(256,240),f.read_bytes(),'raw','BGRA').convert('RGB');dest=a.output/f'{name}-PPU{n}.png';im.save(dest);bind(dest)
  for n in ['oam-bus.jsonl','epochs.jsonl','hud-frames.jsonl','hud-proof.json','config.json','run.lua']:bind(run/n)
  cases.append(dict(profile=name,first_visible_incorrect_epoch=frame,actual_mode=frames[frame]['mode'],first_capture_completed_active0=True,ram_at_visible_start=frames[frame]['start']['ram'],start=ep['start'],finish=ep['finished'],DMA_id=ep['dma']['id'],completed_DMA_source_exact=True,temporary_scroll_address=state['ppu.tmpVideoRamAddr'],current_scroll_address=state['ppu.videoRamAddr'],previous_tmp=epochs[frame-1]['start_state']['ppu.tmpVideoRamAddr'],following_tmp=epochs[frame+1]['start_state']['ppu.tmpVideoRamAddr'],last_necessary_palette_address_writes=addresses[-2:],last_native_scroll_writes=scrolls,events=relevant))
 native=[]
 for name in ['octopus-easy','twinbee-easy','pentarou-easy','octopus-hard','twinbee-hard','pentarou-hard','vic-easy']:
  path=a.base/('hud-native-hard-retry-v1'if name=='octopus-hard'else'hud-native-v1')/name/'baseline-early/hud-proof.json';q=json.loads(path.read_text());assert q['passed'];bind(path);native.append(dict(profile=name,assertion_pass=True,proof=str(path),proof_sha256=sha(path),HOST_FAILURE_RETRY=name=='octopus-hard',updates=q['native']['updates'],DMAs=q['native']['DMAs'],actual_mode=q['actual_mode'],actual_variant=q['actual_variant']))
 for f in [a.base/'hud-native-v1/proof.json',a.base/'hud-native-v1/octopus-hard/baseline-early/hud-proof.json',a.base/'hud-hard-crash-comparison-v2/proof.json',a.base/'hud-hard-crash-comparison-v2/windows-application-error.txt',a.base/'hud-readiness-v1/proof.json',a.base/'hud-readiness-bank126-erratum-v1/proof.json']:bind(f)
 q=dict(visible_qualification_passed=False,source_candidate_held=True,native_worker_released=True,goal_complete=False,ROM_sha256='64f454a248785ff4c53bd0d52158fd2cf5389de38e5c35a888c3e6a6ed982362',cases=cases,completed_assertion_controls=native,VicHard_not_launched=True,HOST_FAILURE_RETRY=True,tool_sha256=sha(Path(__file__)),limits='Seven completed guard controls do not establish a visual pass. Actual first-capture frames show a ground-tile strip in the HUD, despite exact completed DMA and correct subsequent custom labels/font. Necessary palette reads/addresses are legitimate; missing scroll restoration before publication is the source lead. Baseline corresponding native images and every capture-caller policy remain to be qualified before a repair. Original host crash, partial-input telemetry and every earlier negative remain retained.')
 (a.output/'proof.json').write_text(json.dumps(q,indent=2)+'\n',encoding='utf-8');bind(a.output/'proof.json');bind(Path(__file__));shutil.copy2(Path(__file__),a.output/Path(__file__).name);(a.output/'manifest.json').write_text(json.dumps(dict(bindings=bindings),indent=2)+'\n',encoding='utf-8');print(json.dumps(dict(visible_passed=False,completed_controls=len(native),proof_sha256=sha(a.output/'proof.json'),manifest_sha256=sha(a.output/'manifest.json'))))
if __name__=='__main__':main()
